program.source:
Function tax <- Vat(price As Integer)
  Define tax As Integer;
  Write "Computing the VAT";
  tax <- price * 21 Div 100;
EndFunction

Algorithm Main
  Define price As Integer;
  Read price;
  Write "VAT: ", Vat(price);
EndAlgorithm

